public static INettingProcessor construct(
    NettingProcessorType _processorType,
    RecId _executionRecId,
    TransDate _transDate,
    INettingAmountCalculator _nettingAmountCalculator,
    INettingJournalGenerator _nettingJournalGenerator)
{
    CustVendNettingRule             nettingRule;
    INettingJournalGenerator        journalGenerator;
    CustVendNettingExecution        execution;
    CustVendNettingAgreement        agreement;
    CustVendNettingRuleAgreement    ruleAgreement;

    select firstonly execution
        where execution.RecId == _executionRecId
        join agreement
        where agreement.JournalName == execution.JournalName
            join ruleAgreement
            where ruleAgreement.AgreementName == agreement.Name
                join nettingRule
                where nettingRule.Name == ruleAgreement.RuleName;

    if (nettingRule.Sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        journalGenerator = new METCustVendNettingJournalGenerator();
    }
    else
    {
        journalGenerator = _nettingJournalGenerator;
    }
    return next construct(_processorType, _executionRecId, _transDate, _nettingAmountCalculator, journalGenerator);
}
